function logTable(d){const l=E(d).sort((a,b)=>a.start.localeCompare(b.start));return`<table><tr><th>زمان</th><th>فعالیت</th><th>مدت</th><th>یادداشت</th><th></th></tr>${l.map(e=>`<tr><td><bdi dir="ltr">${fT(e.start)}–${fT(e.end)}</bdi></td><td>${esc(aN(e.actId))} <span class="m">${esc(subN(e.actId,e.subId))}</span></td><td>${mm(e.min)}</td><td>${esc(e.note)}</td><td><button data-a="eedit" data-id="${e.id}">ویرایش</button> <button class="d" data-a="edel" data-id="${e.id}">حذف</button></td></tr>`).join('')||'<tr><td colspan="5" class="m">ثبتی برای این روز نیست.</td></tr>'}</table>`}
function rngDates(){const t=todayISO();let a,b;const p=rng.p;if(p==='0')a=b=t;else if(p==='1')a=b=addD(t,-1);else if(p==='7'){a=addD(t,-6);b=t}else if(p==='w'){a=weekStart(t);b=addD(a,6)}else if(p==='m'&&db.set.cal==='g'){const[y,m]=t.split('-').map(Number);a=y+'-'+pad(m)+'-01';b=addD(iso(new Date(y,m,1,12)),-1)}else if(p==='m'){const[y,m]=J(t);a=iso(new Date(...j2g(y,m,1).map((v,i)=>i==1?v-1:v),12));b=addD(a,(m<=6?31:m<=11?30:isLeap(y)?30:29)-1)}else{a=rng.a||t;b=rng.p==='d'?a:(rng.b||a)}return[a,b]}
function repHTML(a,b){if(a>b)return'<div class="c">بازه نامعتبر است: تاریخ شروع بعد از پایان است.</div>';const days=rangeDays(a,b);if(days.length>400)return'<div class="c">بازه بیش از ۴۰۰ روز است؛ کوتاه‌تر انتخاب کنید.</div>';
 const es=E(a,b),wd=days.filter(d=>E(d).length),an=analyze(a,b),tot=sum(es),pl=days.flatMap(d=>plan(d).map(p=>({d,...p}))),pg=days.reduce((s,d)=>{const p=prog(d);return{n:s.n+p.n,w:s.w+p.pc*p.n/100}},{n:0,w:0});
 const pa={};pl.forEach(p=>{pa[p.actId]=pa[p.actId]||{g:0,a:0};pa[p.actId].g+=+p.goal||0;pa[p.actId].a+=actual(p.d,p.actId)});
 const subs={};es.forEach(e=>{const k=e.actId+'|'+(e.subId||'');subs[k]=(subs[k]||0)+e.min});
 const ed=wd.filter(d=>+db.days[d]?.energy>0);const title=a===b?fmtDL(a):fmtD(a)+' تا '+fmtD(b);
 return`<div class="c"><h2 style="margin:0">گزارش جامع DANI</h2><b>${title}</b><div class="m">تولید: ${new Date().toLocaleString((LANGEN()?'en-US':'fa-IR'))} · داده‌ها فقط از ثبت‌های واقعی ساخته شده‌اند</div></div>
 <div class="g g4" style="margin:10px 0"><div class="c"><div class="m">روزهای بازه / دارای داده</div><b>${fa(days.length)} / ${fa(wd.length)}</b></div><div class="c"><div class="m">تعداد ثبت</div><b>${fa(new Set(es.map(e=>e.id)).size)}</b></div><div class="c"><div class="m">مجموع زمان ثبت‌شده</div><b>${mm(tot)}</b></div><div class="c"><div class="m">میانگین روزهای دارای داده</div><b>${mm(wd.length?tot/wd.length:0)}</b></div></div>
 <div class="c"><h3>خلاصه اجرایی (تحلیل خودکار مبتنی بر داده‌ها)</h3>${an.str.map(s=>'<p>✓ '+esc(s)+'</p>').join('')||'<p class="m">—</p>'}${pg.n?`<p>پایبندی به برنامه: ${fa(Math.round(pg.w/pg.n*100))}٪ (${fa(pg.n)} مورد برنامه‌ریزی‌شده)</p>`:'<p class="m">برای این بازه برنامه‌ای ثبت نشده است.</p>'}</div>
 <div class="g g2" style="margin-top:10px"><div class="c"><h3>زمان هر فعالیت</h3>${bars(actList(es))}</div><div class="c"><h3>توزیع دسته‌ها</h3>${donut(catList(es))}</div>
 <div class="c"><h3>روند روزانه (کل ثبت‌شده)</h3>${line(days.map(d=>({l:fmtD(d),v:sum(E(d))})))}</div><div class="c"><h3>برنامه در برابر عملکرد (هدف ← واقعی)</h3>${Object.keys(pa).length?bars(Object.entries(pa).map(([k,v])=>({l:aN(k)+' — هدف '+mm(v.g),v:v.a,c:v.a>=v.g?'var(--ok)':'var(--wr)'}))):'<p class="m">برنامه‌ای نیست</p>'}</div></div>
 <div class="c" style="margin-top:10px"><h3>جزئیات فعالیت و زیرمجموعه</h3><table><tr><th>فعالیت</th><th>زیرمجموعه</th><th>زمان</th></tr>${Object.entries(subs).sort((x,y)=>y[1]-x[1]).map(([k,v])=>{const[i,s]=k.split('|');return`<tr><td>${esc(aN(i))}</td><td>${esc(subN(i,s))||'—'}</td><td>${mm(v)}</td></tr>`}).join('')||'<tr><td colspan="3" class="m">داده‌ای نیست</td></tr>'}</table><p class="m">زمان زیرمجموعه‌ها در زمان فعالیت مادر تجمیع می‌شود و هر ثبت فقط یک‌بار شمرده می‌شود.</p></div>
 ${days.length<=14?`<div class="c" style="margin-top:10px"><h3>خط زمانی روزها (با بازه‌های ثبت‌نشده)</h3>${days.map(d=>`<h4>${fmtDL(d)}${db.days[d]?.energy?' · انرژی '+fa(db.days[d].energy)+'/۱۰':''}</h4>${tlHTML(d)}`).join('')}</div>`:''}
 ${ed.length?`<div class="c" style="margin-top:10px"><h3>انرژی و تمرکز</h3>${ed.map(d=>`${fmtD(d)}: انرژی ${fa(db.days[d].energy)}، تمرکز ${fa(db.days[d].focus||'—')}`).join('<br>')}</div>`:''}
 <div class="g g2" style="margin-top:10px"><div class="c"><h3>واقعیت‌های ثبت‌شده</h3>${an.str.map(s=>'<p>'+esc(s)+'</p>').join('')||'—'}</div><div class="c"><h3>برداشت‌های احتمالی و محدودیت‌ها</h3>${an.lim.map(s=>'<p>'+esc(s)+'</p>').join('')||'—'}</div></div>
 <div class="c" style="margin-top:10px"><h3>پیشنهادهای اصلاحی (حداکثر ۳) <span class="m">· اطمینان: ${confOf(an)}</span></h3>${an.tips.map(s=>'<p>• '+esc(s)+'</p>').join('')||'<p class="m">پیشنهادی نیست.</p>'}${wd.map(d=>db.days[d]).filter(x=>x&&(x.learned||x.barrier||x.tomorrow)).map(x=>`<hr><p>یادگیری: ${esc(x.learned||'—')}<br>مانع: ${esc(x.barrier||'—')}<br>تعهد فردا: ${esc(x.tomorrow||'—')}</p>`).join('')}</div>
 <p class="m">روش محاسبه: زمان ثبت‌شده = جمع دقیقه‌های ثبت‌ها؛ زمان ثبت‌نشده = بخش‌های خالی بین ${fT(db.set.ds)} تا ${fT(db.set.de)}؛ زمان ثبت‌نشده مساوی اتلاف وقت نیست.</p>`}
