function dl(name,mime,txt){const u=URL.createObjectURL(new Blob(['\ufeff'+txt],{type:mime+';charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('فایل ساخته شد: '+name)}
const safeCell=v=>{v=String(v??'');return /^[=+\-@\t\r]/.test(v)&&!/^-?\d+([.,]\d+)?$/.test(v)?"'"+v:v};const csvE=l=>(LANGEN()?'date,start,end,minutes,activity,sub-item,category,note\n':'تاریخ,شروع,پایان,دقیقه,فعالیت,زیرمجموعه,دسته,یادداشت\n')+l.map(e=>[e.date,e.start,e.end,e.min,aN(e.actId),subN(e.actId,e.subId),CATS[cat(e)]?.[0],e.note].map(v=>'"'+safeCell(v).replace(/"/g,'""')+'"').join(',')).join('\n');
function repCSS(){return'body{font-family:"B Nazanin",Vazirmatn,Tahoma,sans-serif;direction:rtl;line-height:1.7;color:#111}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:4px;text-align:start}.c{border:1px solid #ddd;border-radius:8px;padding:8px;margin:6px 0;page-break-inside:avoid}.g{display:block}.bar{height:8px;background:#e5e7eb}.bar i{display:block;height:100%;background:#16a34a}.row{display:block}.tl div{display:block;border-bottom:1px dashed #ccc}svg{max-width:100%}'}
function doExport(k){const[a,b]=rngDates();if(a>b)return toast('بازه نامعتبر است',1);
 if(k==='csv'){const l=ER(a,b);if(!l.length)return toast('در این بازه داده‌ای نیست',1);dl(`hamrah-${a}_${b}.csv`,'text/csv',csvE(l))}
 else if(k==='docx')docxExport(a,b);
 else if(k==='doc')dl(`hamrah-report-${a}_${b}.doc`,'application/msword',`<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>${repCSS()}</style></head><body>${repHTML(a,b)}</body></html>`);
 else if(k==='pdf'){const w=window.open('','_blank');if(!w)return toast('پنجره‌ی چاپ مسدود شد؛ پاپ‌آپ را مجاز کنید',1);w.document.write(`<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>گزارش DANI</title><style>${repCSS()}</style></head><body>${repHTML(a,b)}<script>setTimeout(()=>print(),400)<\/script></body></html>`);w.document.close()}}
function exportJSON(){db.set.lastBk=Date.now();save();dl('hamrah-backup-'+todayISO()+'.json','application/json',JSON.stringify({app:'hamrah',version:3,exportedAt:new Date().toISOString(),db},null,1))}
function restoreFile(f){const r=new FileReader();r.onerror=()=>toast('خواندن فایل ممکن نشد',1);r.onload=()=>{let m;try{m=migrate(JSON.parse(r.result));vetImport(m)}catch(e){return toast(e instanceof SyntaxError?'فایل JSON خراب است و خوانده نشد؛ داده‌های فعلی تغییری نکرد':'فایل نامعتبر: '+e.message,1)}
 const x=m.db;window._rs=x;modal(`<h3>بررسی فایل پشتیبان</h3><p>${fa(x.acts.length)} فعالیت · ${fa(x.entries.length)} ثبت · بازه‌ی تاریخ: ${x.entries.length?fmtD(x.entries.map(e=>e.date).sort()[0])+' تا '+fmtD(x.entries.map(e=>e.date).sort().pop()):'—'}</p><p class="m">${m.rep.map(esc).join('<br>')}</p><p>قبل از هر تغییر، یک نسخه‌ی کامل از داده‌ی فعلی در مرورگر نگه‌داری می‌شود.</p><div class="row"><button class="d" data-a="rrep">جایگزینی کامل داده‌ها</button><button class="p" data-a="rmer">ادغام (بدون حذف داده‌ی فعلی)</button><button data-a="cl">انصراف</button></div>`)};r.readAsText(f)}
function snap(){try{localStorage.setItem('hamrah_v3_snapshot',JSON.stringify(db))}catch(e){throw new Error('تهیه‌ی نسخه‌ی پشتیبان ممکن نشد؛ عملیات انجام نشد')}}
function merge(x){const ids=new Set(db.acts.map(a=>a.id)),nm=new Set(db.acts.map(a=>a.name));let na=0,ne=0,sk=0;x.acts.forEach(a=>{if(ids.has(a.id))return;if(nm.has(a.name)){sk++;a._remap=db.acts.find(z=>z.name===a.name).id;return}db.acts.push(a);na++});
 const map={};x.acts.forEach(a=>{if(a._remap)map[a.id]=a._remap});const eid=new Set(db.entries.map(e=>e.id));x.entries.forEach(e=>{if(eid.has(e.id))return;e.actId=map[e.actId]||e.actId;db.entries.push(e);ne++});
 Object.entries(x.days).forEach(([d,v])=>{if(!db.days[d])db.days[d]=v});Object.entries(x.plans).forEach(([d,v])=>{if(!db.plans[d])db.plans[d]=v});x.notes.forEach(n=>{if(!db.notes.some(z=>z.id===n.id))db.notes.push(n)});return`ادغام شد: ${fa(na)} فعالیت جدید، ${fa(ne)} ثبت جدید؛ ${fa(sk)} فعالیت هم‌نام با فعالیت موجود یکی‌شده به‌صورت ثبت‌ها (نام‌ها خودکار یکی نمی‌شوند مگر دقیقاً برابر)`}
