 if(s&&e2){if(s===e2)return toast('زمان شروع و پایان برابر است',1);st=s;en=e2;min=dur(s,e2)}else if(s&&m>0){st=s;min=m;en=hm(tm(s)+m)}else return toast('شروع و پایان، یا شروع و مدت را وارد کنید',1);
